css:
body{margin:0;background:#070B1B}
*{box-sizing:border-box}
.apw{--bg:#FFFFFF;--bg2:#F6F4EF;--bg3:#E4EEF8;--card:#FFFFFF;--ink:#0E1430;--ink2:#3E4668;--mute:#4A5272;--line:#E2DDD2;--field:#8A91B0;--accent:#FF4A1C;--accent-hi:#FF6B42;--accent-ink:#0E1430;--accent-text:#B02A08;--accent-soft:#FFE1D6;--ok:#1E7A52;--ok-soft:#E3F1EA;--band:#0A0F24;--band2:#111936;--shadow:0 14px 34px rgba(10,15,36,.14);font-family:"Schibsted Grotesk",ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
.apw.dark{--bg:#0A0F24;--bg2:#0E1530;--bg3:#101A38;--card:#141D3D;--ink:#F6F4EF;--ink2:#D5DAF0;--mute:#AEB5D8;--line:rgba(255,255,255,.13);--field:#6B7398;--accent-text:#FF8A66;--accent-soft:rgba(255,74,28,.16);--ok:#4CC38A;--ok-soft:rgba(76,195,138,.15);--band:#070B1B;--band2:#111936;--shadow:0 14px 34px rgba(0,0,0,.45)}
.apw a{color:var(--accent-text)}
.mono{font-family:"IBM Plex Mono",ui-monospace,Consolas,monospace}
.wm{font-family:"Archivo","Arial Black",sans-serif;font-weight:800;text-transform:uppercase;letter-spacing:.045em;line-height:1}
.eb{margin:0;font-family:"IBM Plex Mono",ui-monospace,Consolas,monospace;font-size:13px;font-weight:600;letter-spacing:.09em;text-transform:uppercase;color:var(--accent-text)}
.h1{margin:0;font-weight:800;letter-spacing:-.05em;line-height:.95;text-wrap:balance}
.h2{margin:10px 0 0;font-size:34px;font-weight:800;letter-spacing:-.045em;line-height:1;text-wrap:balance}
.lead{margin:12px 0 0;font-size:17px;line-height:1.55;color:var(--ink2)}
.btn{display:flex;align-items:center;justify-content:center;gap:10px;min-height:56px;padding:0 24px;border-radius:999px;border:1.6px solid transparent;font:inherit;font-size:18px;font-weight:700;line-height:1;cursor:pointer;text-decoration:none;white-space:nowrap}
.btn:disabled{opacity:.45;cursor:not-allowed}
.apw .btn-dot{background:var(--accent);color:var(--accent-ink)}.apw .btn-dot:hover{background:var(--accent-hi);color:var(--accent-ink)}
.apw .btn-ink{background:var(--ink);color:var(--bg)}
.apw .btn-line{background:transparent;color:var(--ink);border-color:var(--field)}
.apw .btn-line-n{background:transparent;color:#FFFFFF;border-color:rgba(255,255,255,.3)}
.apw .btn-pay{background:#000000;color:#FFFFFF;border-color:#000000}
.apw.dark .btn-pay{border-color:rgba(255,255,255,.4)}
.ibtn{width:48px;height:48px;flex:0 0 48px;display:grid;place-items:center;border-radius:50%;border:1.6px solid var(--line);background:transparent;color:var(--ink);cursor:pointer;padding:0;text-decoration:none}
.apw .ibtn-n{border-color:rgba(255,255,255,.24);color:#F6F4EF}
.ldot{display:inline-block;width:9px;height:9px;flex:0 0 9px;border-radius:50%;background:#FF4A1C;animation:apwBlink 1.6s ease-out infinite}
details>summary{list-style:none;cursor:pointer}details>summary::-webkit-details-marker{display:none}
.chev{transition:transform .2s ease}details[open]>summary .chev{transform:rotate(45deg)}
@keyframes apwBlink{0%{box-shadow:0 0 0 0 rgba(255,74,28,.6)}70%{box-shadow:0 0 0 8px rgba(255,74,28,0)}100%{box-shadow:0 0 0 0 rgba(255,74,28,0)}}
@media (prefers-reduced-motion:reduce){.ldot{animation:none}}
input:focus-visible,button:focus-visible,a:focus-visible,summary:focus-visible,textarea:focus-visible,ul:focus-visible{outline:3px solid #FF6B42;outline-offset:2px}
.apw .bh1{margin:0;font-size:32px;font-weight:800;letter-spacing:-.045em;line-height:1;text-wrap:balance;outline:none}
.apw .flab{display:block;margin-top:16px;font-size:15px;font-weight:700}
.apw .fin{display:block;width:100%;height:54px;margin-top:6px;padding:0 16px;border-radius:14px;border:1.6px solid var(--field);background:var(--card);color:var(--ink);font:inherit;font-size:17px}
.apw .ferr{margin:6px 0 0;font-size:14px;font-weight:700;color:var(--accent-text)}
.apw .cbx{display:flex;gap:12px;align-items:flex-start;margin-top:10px;padding:14px;border-radius:16px;border:1.6px solid var(--field);background:var(--card);cursor:pointer}
.apw .cbx input{width:24px;height:24px;flex:0 0 24px;margin:1px 0 0;accent-color:#FF4A1C}
.apw .cbx b{display:block;font-size:16px;line-height:1.3}
.apw .cbx small{display:block;margin-top:3px;font-size:14px;line-height:1.45;color:var(--mute)}
.apw .fine{margin:12px 0 0;font-size:13px;line-height:1.55;color:var(--mute)}
.apw .fine a,.apw .tlink{color:var(--ink);font-weight:700}
.apw .tlink{display:inline-flex;align-items:center;min-height:44px;padding:0;border:0;background:none;font:inherit;font-size:16px;cursor:pointer;text-decoration:underline;text-underline-offset:3px}
.apw .note{display:flex;gap:12px;align-items:flex-start;margin-top:14px;padding:14px 16px;border-radius:16px;background:var(--bg2);font-size:15px;line-height:1.5;color:var(--ink2)}
.apw .demo{display:inline-flex;align-items:center;gap:8px;margin-top:14px;padding:6px 12px;border-radius:999px;background:var(--bg2);border:1px dashed var(--field);font-size:13px;font-weight:700;color:var(--mute)}
.apw .paybox{margin-top:16px;min-height:120px;border-radius:16px;overflow:hidden}

script:
class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = Object.assign({
      dark: this._themeFromProps(), step: 0, zip: '', dogs: 2, plan: 'week', dayIso: '',
      name: '', phone: '', email: '', addr: '', txtVisit: false, txtDeals: false, tried: false,
      wait: '', waitDone: false, waitBusy: false, waitErr: '',
      code: '', codeErr: '', resent: false, busy: false, err: '',
      payState: 'idle', payErr: '', cal: false
    }, this._initial());
  }
  componentDidMount() { this._themeInit(); }
  componentWillUnmount() { this._themeStop(); this._stopPay(); }
  _themeFromProps() {
    const pt = this.props.theme || 'light';
    if (pt === 'dark') return true;
    if (pt === 'auto' && typeof window !== 'undefined' && window.matchMedia) return window.matchMedia('(prefers-color-scheme: dark)').matches;
    return false;
  }
  _themeInit() {
    if (typeof window === 'undefined' || !window.matchMedia) return;
    this._mq = window.matchMedia('(prefers-color-scheme: dark)');
    this._mqf = () => { if ((this.props.theme || 'light') === 'auto') this.setState({ dark: this._mq.matches }); };
    if (this._mq.addEventListener) this._mq.addEventListener('change', this._mqf);
  }
  _themeStop() {
    if (this._mq && this._mq.removeEventListener) this._mq.removeEventListener('change', this._mqf);
  }
  componentDidUpdate(prev) {
    if (prev.theme !== this.props.theme) this.setState({ dark: this._themeFromProps() });
  }
  _themeVals() {
    const d = !!this.state.dark;
    return {
      themeClass: d ? 'dark' : 'light',
      isDark: d,
      isLight: !d,
      themeLabel: d ? 'Switch to the light look' : 'Switch to the dark look',
      themeMenuLabel: d ? 'Light look' : 'Dark look',
      toggleTheme: () => this.setState({ dark: !this.state.dark })
    };
  }
  _price(id, dogs) {
    const base = { week: 108, twice: 189, eow: 75 };
    const extra = { week: 13, twice: 13, eow: 9 };
    return base[id] + Math.max(0, dogs - 2) * extra[id];
  }
  _per(id, dogs) {
    const visits = { week: 52 / 12, twice: 104 / 12, eow: 26 / 12 };
    return Math.round(this._price(id, dogs) / visits[id]);
  }
  _cal(id, onBand) {
    const out = [];
    for (let i = 0; i < 28; i++) {
      const d = i % 7;
      const w = Math.floor(i / 7);
      const on = id === 'week' ? d === 2 : id === 'twice' ? (d === 2 || d === 5) : (d === 2 && w % 2 === 0);
      out.push({ bg: on ? '#FF4A1C' : (onBand ? 'rgba(255,255,255,.16)' : 'var(--line)') });
    }
    return out;
  }
  _plans(onBand) {
    const s = this.state;
    const names = { week: 'Every week', twice: 'Twice a week', eow: 'Every other week' };
    return ['week', 'twice', 'eow'].map((id) => {
      const on = s.plan === id;
      return {
        id: id,
        name: names[id],
        price: '$' + this._price(id, s.dogs),
        per: 'About $' + this._per(id, s.dogs) + ' a visit',
        on: on,
        pick: () => this.setState({ plan: id }),
        aria: names[id] + ', $' + this._price(id, s.dogs) + ' a month',
        cal: this._cal(id, onBand),
        border: on ? '#FF4A1C' : (onBand ? 'rgba(255,255,255,.18)' : 'var(--field)'),
        bg: on ? 'rgba(255,74,28,.12)' : 'transparent',
        ring: on ? '#FF4A1C' : (onBand ? '#AEB5D8' : 'var(--mute)'),
        dot: on ? '#FF4A1C' : 'transparent'
      };
    });
  }
  componentDidUpdate(prevProps, prev) {
    const s = this.state;
    if (prev.step !== s.step) {
      if (prev.step === 5) this._stopPay();
      if (s.step === 5) this._startPay();
      this._focusStep();
    }
    if (s.step < 5) this._save();
  }
  _apw() { return typeof window !== 'undefined' ? window.APW || null : null; }
  _cfg() { const a = this._apw(); return (a && a.cfg) || {}; }
  _demo() { const a = this._apw(); return !a || !a.live; }
  _closed() { const a = this._apw(); return !!(a && a.closed); }
  _zips() { return { '85396': 'Verrado', '85355': 'Citrus Park', '85395': 'Goodyear', '85340': 'Litchfield Park' }; }
  _initial() {
    if (typeof window === 'undefined') return {};
    const out = {};
    try { Object.assign(out, JSON.parse(sessionStorage.getItem('apw.book') || '{}')); } catch (e) { }
    if (this.props.mode === 'page') {
      const q = new URLSearchParams(location.search);
      if (/^\d{5}$/.test(q.get('zip') || '')) out.zip = q.get('zip');
      if (['week', 'twice', 'eow'].indexOf(q.get('plan')) >= 0) out.plan = q.get('plan');
      const n = parseInt(q.get('dogs'), 10);
      if (n >= 1 && n <= 6) out.dogs = n;
    }
    if (out.step > 3 || out.step < 0 || typeof out.step !== 'number') out.step = 0;
    if (out.step > 0 && !this._zips()[out.zip]) out.step = 0;
    return out;
  }
  _save() {
    if (typeof window === 'undefined') return;
    const s = this.state;
    const keep = { step: Math.min(s.step, 3), zip: s.zip, dogs: s.dogs, plan: s.plan, dayIso: s.dayIso, name: s.name, phone: s.phone, email: s.email, addr: s.addr, txtVisit: s.txtVisit, txtDeals: s.txtDeals };
    try { sessionStorage.setItem('apw.book', JSON.stringify(keep)); } catch (e) { }
  }
  _clearDraft() { try { sessionStorage.removeItem('apw.book'); } catch (e) { } }
  _focusStep() {
    if (typeof document === 'undefined' || !this.__root) return;
    const body = this.__root.querySelector('.bk-body');
    if (body) body.scrollTop = 0;
    const h = this.__root.querySelector('.bh1');
    if (h && h.focus) { try { h.focus({ preventScroll: true }); } catch (e) { h.focus(); } }
  }
  _iso(d) { return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); }
  _days() {
    const cfg = this._cfg();
    const lead = typeof cfg.leadDays === 'number' ? cfg.leadDays : 2;
    const from = cfg.firstVisitFrom || '2026-11-20';
    const off = cfg.noVisitDays || ['2026-11-26', '2026-11-27', '2026-12-24', '2026-12-25', '2026-12-31', '2027-01-01'];
    const d = new Date();
    d.setHours(12, 0, 0, 0);
    d.setDate(d.getDate() + lead);
    const f = new Date(from + 'T12:00:00');
    if (f > d) d.setTime(f.getTime());
    const out = [];
    let guard = 0;
    while (out.length < 6 && guard++ < 60) {
      const w = d.getDay();
      const iso = this._iso(d);
      if (w !== 0 && w !== 6 && off.indexOf(iso) < 0) {
        out.push({
          iso: iso,
          wd: d.toLocaleDateString('en-US', { weekday: 'short' }),
          md: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
          full: d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' }),
          date: new Date(d.getTime())
        });
      }
      d.setDate(d.getDate() + 1);
    }
    return out;
  }
  _digits(v, n) { return String(v || '').replace(/\D/g, '').slice(0, n); }
  _phone10() { let p = String(this.state.phone || '').replace(/\D/g, ''); if (p.length === 11 && p[0] === '1') p = p.slice(1); return p; }
  _errs() {
    const s = this.state;
    return {
      name: s.name.trim().length < 2 ? 'Type your full name.' : '',
      phone: this._phone10().length === 10 ? '' : 'Type your 10 digit mobile number.',
      email: /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(s.email.trim()) ? '' : 'Type your email, like you@email.com.',
      addr: s.addr.trim().length < 5 ? 'Type your street address.' : ''
    };
  }
  _go(step) { this.setState({ step: step, err: '', busy: false }); }
  _next() {
    const s = this.state;
    if (s.busy) return;
    if (s.step === 0) { if (this._zips()[s.zip]) this._go(1); return; }
    if (s.step === 1) return this._go(2);
    if (s.step === 2) { if (!s.dayIso) this.setState({ dayIso: this._days()[0].iso }); return this._go(3); }
    if (s.step === 3) {
      const e = this._errs();
      if (e.name || e.phone || e.email || e.addr) { this.setState({ tried: true }); return; }
      if (this._closed()) { this.setState({ err: 'Online sign up opens soon. Call or text 623.309.6104 and we will book you today.' }); return; }
      return this._signIn();
    }
    if (s.step === 4) return this._verify();
    if (s.step === 5 && this._demo()) return this._go(6);
  }
  async _signIn() {
    const a = this._apw();
    const email = this.state.email.trim();
    if (this._demo()) { this.setState({ step: 4, code: '', codeErr: '', resent: false }); return; }
    const sess = a.auth.session();
    if (sess && sess.email && sess.email.toLowerCase() === email.toLowerCase()) { this._go(5); return; }
    this.setState({ busy: true, err: '' });
    try {
      await a.auth.sendCode(email);
      this.setState({ busy: false, step: 4, code: '', codeErr: '', resent: false });
    } catch (e) {
      this.setState({ busy: false, err: a.msg(e) });
    }
  }
  async _verify() {
    const code = this._digits(this.state.code, 6);
    if (code.length !== 6) { this.setState({ codeErr: 'Type the 6 numbers from the email.' }); return; }
    if (this._demo()) { this._go(5); return; }
    this.setState({ busy: true, codeErr: '' });
    try {
      await this._apw().auth.verifyCode(this.state.email.trim(), code);
      this._go(5);
    } catch (e) {
      this.setState({ busy: false, codeErr: 'That code did not work. Check the email and try again, or send a new code.' });
    }
  }
  async _resend() {
    if (this.state.busy) return;
    if (this._demo()) { this.setState({ resent: true }); return; }
    this.setState({ busy: true, codeErr: '' });
    try { await this._apw().auth.sendCode(this.state.email.trim()); this.setState({ busy: false, resent: true }); }
    catch (e) { this.setState({ busy: false, codeErr: this._apw().msg(e) }); }
  }
  async _joinWait() {
    const s = this.state;
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(s.wait.trim())) { this.setState({ waitErr: 'Type your email, like you@email.com.' }); return; }
    if (this._closed()) { this.setState({ waitErr: 'Text 623.309.6104 with your ZIP and we will add you to the list.' }); return; }
    if (this._demo()) { this.setState({ waitDone: true, waitErr: '' }); return; }
    this.setState({ waitBusy: true, waitErr: '' });
    try { await this._apw().post('/api/waitlist', { email: s.wait.trim(), zip: s.zip, website: '' }); this.setState({ waitBusy: false, waitDone: true }); }
    catch (e) { this.setState({ waitBusy: false, waitErr: this._apw().msg(e) }); }
  }
  async _startPay() {
    if (this._demo()) return;
    const a = this._apw();
    const s = this.state;
    const tok = this._payTok = (this._payTok || 0) + 1;
    this.setState({ payState: 'loading', payErr: '' });
    try {
      const days = this._days();
      const r = await a.post('/api/checkout', {
        zip: s.zip, plan: s.plan, dogs: s.dogs, firstVisit: s.dayIso || days[0].iso,
        name: s.name.trim(), phone: this._phone10(), email: s.email.trim(), address: s.addr.trim(),
        textsVisit: !!s.txtVisit, textsDeals: !!s.txtDeals, page: location.pathname
      }, true);
      if (tok !== this._payTok) return;
      if (r && r.already) { this.setState({ payState: 'already' }); return; }
      const stripe = await a.stripe();
      if (tok !== this._payTok || this.state.step !== 5) return;
      const init = (stripe.initEmbeddedCheckout || stripe.createEmbeddedCheckoutPage).bind(stripe);
      const ck = await init({ fetchClientSecret: () => Promise.resolve(r.clientSecret), onComplete: () => this._paid() });
      if (tok !== this._payTok || this.state.step !== 5) { try { ck.destroy(); } catch (e) { } return; }
      const box = this.__root && this.__root.querySelector('[data-pay-mount]');
      this._checkout = ck;
      ck.mount(box);
      this.setState({ payState: 'ready' });
    } catch (e) {
      if (tok === this._payTok) this.setState({ payState: 'error', payErr: a.msg(e) });
    }
  }
  _stopPay() {
    this._payTok = (this._payTok || 0) + 1;
    if (this._checkout) { try { this._checkout.destroy(); } catch (e) { } this._checkout = null; }
  }
  _paid() {
    this._stopPay();
    this._clearDraft();
    const a = this._apw();
    if (a && a.track) a.track('booked');
    this.setState({ step: 6, payState: 'idle' });
  }
  _addCal() {
    const s = this.state;
    const days = this._days();
    const day = days.filter((x) => x.iso === s.dayIso)[0] || days[0];
    const ymd = day.iso.replace(/-/g, '');
    const end = new Date(day.date.getTime()); end.setDate(end.getDate() + 1);
    const ymd2 = this._iso(end).replace(/-/g, '');
    const stamp = new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d+Z$/, 'Z');
    const rule = s.plan === 'eow' ? 'FREQ=WEEKLY;INTERVAL=2' : 'FREQ=WEEKLY';
    const ics = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Arizona Pet Waste//Booking//EN', 'BEGIN:VEVENT',
      'UID:apw-' + ymd + '-' + Math.random().toString(36).slice(2) + '@arizonapetwaste.com', 'DTSTAMP:' + stamp,
      'DTSTART;VALUE=DATE:' + ymd, 'DTEND;VALUE=DATE:' + ymd2, 'RRULE:' + rule,
      'SUMMARY:Arizona Pet Waste visit', 'DESCRIPTION:We text you the night before with a 30 minute window. Questions? Text 623.309.6104.',
      'END:VEVENT', 'END:VCALENDAR'].join('\r\n');
    try {
      const url = URL.createObjectURL(new Blob([ics], { type: 'text/calendar' }));
      const link = document.createElement('a');
      link.href = url; link.download = 'arizona-pet-waste-visits.ics';
      document.body.appendChild(link); link.click(); link.remove();
      setTimeout(() => URL.revokeObjectURL(url), 4000);
    } catch (e) { }
    this.setState({ cal: true });
  }
  open(o) {
    const s = this.state;
    const next = {};
    if (s.step <= 2 || s.step === 6) {
      if (o.plan) next.plan = o.plan;
      if (o.dogs) next.dogs = o.dogs;
      if (o.zip && this._zips()[o.zip]) next.zip = o.zip;
      const zip = next.zip || s.zip;
      if (s.step === 6) next.step = 0;
      if ((s.step === 0 || s.step === 6) && this._zips()[zip]) next.step = 1;
    }
    this.setState(next);
  }
  renderVals() {
    const s = this.state;
    const zips = this._zips();
    const cities = { '85396': 'Buckeye, AZ 85396', '85355': 'Waddell, AZ 85355', '85395': 'Goodyear, AZ 85395', '85340': 'Litchfield Park, AZ 85340' };
    const names = { week: 'Every week', twice: 'Twice a week', eow: 'Every other week' };
    const zipOk = !!zips[s.zip];
    const days = this._days();
    const day = days.filter((x) => x.iso === s.dayIso)[0] || days[0];
    const price = this._price(s.plan, s.dogs);
    const dogsLabel = s.dogs === 1 ? '1 dog' : s.dogs + ' dogs';
    const charge = new Date(day.date.getTime());
    const dd = charge.getDate();
    charge.setDate(1);
    charge.setMonth(charge.getMonth() + 1);
    charge.setDate(Math.min(dd, new Date(charge.getFullYear(), charge.getMonth() + 1, 0).getDate()));
    const chargeDay = charge.toLocaleDateString('en-US', { month: 'long', day: 'numeric' });
    const inFlow = s.step > 0 && s.step < 6;
    const demo = this._demo();
    const errs = s.tried ? this._errs() : { name: '', phone: '', email: '', addr: '' };
    const tone = (on) => ({ border: on ? 'var(--ink)' : 'var(--field)', bg: on ? 'var(--ink)' : 'var(--card)', fg: on ? 'var(--bg)' : 'var(--ink)' });
    const field = (k) => (e) => { const o = {}; o[k] = e.target.value; this.setState(o); };
    const dock = this.props.mode === 'dock';
    const labels = ['Continue', 'Continue', 'Continue', 'Continue', 'Check code', 'Finish demo booking', ''];
    return Object.assign({}, this._themeVals(), {
      s0: s.step === 0, s1: s.step === 1, s2: s.step === 2, s3: s.step === 3, s4: s.step === 4, s5: s.step === 5, s6: s.step === 6,
      topTitle: s.step === 6 ? 'Arizona Pet Waste' : 'Start your free month',
      canBack: inFlow,
      noBack: !inFlow,
      back: () => this.setState({ step: Math.max(0, s.step === 5 ? 3 : s.step - 1), busy: false, err: '', codeErr: '' }),
      closeLabel: dock ? 'Close' : 'Close and go to the home page',
      close: (e) => { const a = this._apw(); if (dock && a && a.closeBook) { e.preventDefault(); a.closeBook(); } },
      showProgress: s.step < 6,
      segs: [0, 1, 2, 3, 4, 5].map((i) => ({ bg: i <= s.step ? 'var(--accent)' : 'var(--line)' })),
      stepLabel: 'Step ' + (s.step + 1) + ' of 6',
      showBar: s.step < 5 || (s.step === 5 && demo),
      showSum: s.step >= 1 && s.step <= 3,
      priceShort: '$' + price + '/mo',
      planShort: names[s.plan] + ' · ' + dogsLabel,
      nextOff: (s.step === 0 && !zipOk) || s.busy,
      nextLabel: s.busy ? 'One moment…' : labels[s.step],
      next: () => this._next(),
      enter: (e) => { if (e.key === 'Enter') { e.preventDefault(); this._next(); } },
      zip: s.zip,
      onZip: (e) => this.setState({ zip: this._digits(e.target.value, 5), waitDone: false, waitErr: '' }),
      zipOk: zipOk,
      zipNo: s.zip.length === 5 && !zipOk,
      zipPlace: zips[s.zip] || '',
      wait: s.wait,
      onWait: field('wait'),
      waitOpen: !s.waitDone,
      waitDone: s.waitDone,
      waitBusy: s.waitBusy,
      waitErr: s.waitErr,
      joinWait: () => this._joinWait(),
      dogOpts: [1, 2, 3, 4, 5, 6].map((n) => Object.assign({
        label: String(n),
        aria: n === 1 ? '1 dog' : n + ' dogs',
        on: s.dogs === n,
        pick: () => this.setState({ dogs: n })
      }, tone(s.dogs === n))),
      plans: this._plans(false),
      days: days.map((x) => Object.assign({}, x, { on: day.iso === x.iso, pick: () => this.setState({ dayIso: x.iso }) }, tone(day.iso === x.iso))),
      name: s.name, onName: field('name'),
      phone: s.phone, onPhone: field('phone'),
      email: s.email, onEmail: field('email'),
      addr: s.addr, onAddr: field('addr'),
      eName: errs.name, ePhone: errs.phone, eEmail: errs.email, eAddr: errs.addr,
      txtVisit: !!s.txtVisit, onTxtVisit: (e) => this.setState({ txtVisit: !!e.target.checked }),
      txtDeals: !!s.txtDeals, onTxtDeals: (e) => this.setState({ txtDeals: !!e.target.checked }),
      err: s.err,
      cityLine: cities[s.zip] || 'Buckeye, AZ 85396',
      code: s.code,
      onCode: (e) => { const v = this._digits(e.target.value, 6); this.setState({ code: v, codeErr: '' }); if (v.length === 6) setTimeout(() => this._verify(), 60); },
      codeErr: s.codeErr,
      isDemo: demo,
      resend: () => this._resend(),
      resendLabel: s.resent ? 'We sent a new code' : 'Send a new code',
      planName: names[s.plan],
      dogsLabel: dogsLabel,
      dayFull: day.full,
      priceLabel: '$' + price,
      billLine: 'Your first month is free. Your card is charged $' + price + ' on ' + chargeDay + ', then once a month. Cancel before then and you pay $0.',
      payDemo: demo,
      payLive: !demo && s.payState !== 'already',
      payLoading: !demo && s.payState === 'loading',
      payError: !demo && s.payState === 'error',
      payAlready: !demo && s.payState === 'already',
      payErr: s.payErr,
      retryPay: () => this._startPay(),
      doneLine: s.txtVisit ? 'We will text you the night before.' : 'We will email you the night before.',
      calLabel: s.cal ? 'Added to your calendar' : 'Add to my calendar',
      addCal: () => this._addCal()
    });
  }
}
